public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int fish = sc.nextInt();
        int cats = sc.nextInt();
        try {
            System.out.println("每只猫分到 " + fish / cats + " 条喵");
        } catch (ArithmeticException e) {
            System.out.println("没有猫来分，这条算不了喵");
        }
        System.out.println("分账结束喵");
    }
}

